/**
 * engine-server/llm-client.ts — LLM 调用客户端
 *
 * 通过 Gateway /v1/chat/completions 调用 LLM。
 * Gateway 不可用时 fallback 到出厂 Key 直连 DeepSeek。
 * 所有外部调用必须有 AbortSignal 超时。
 *
 * @packageDocumentation
 */

import {
  GATEWAY_HOST,
  LLM_MODEL,
  LLM_TIMEOUT_MS,
  LLM_MAX_TOKENS,
  LLM_TEMPERATURE,
  DEEPSEEK_API_KEY,
} from './pipeline-config';
import type { LLMChatCompletionResponse } from './types/llm';

// 使用 node-fetch 替代内置 fetch（Windows 环境下内置 fetch 可能不可用）
import nodeFetch from 'node-fetch';
import { createLogger } from './infra/logger';
import { getEngineContext, CircuitOpenError, type CircuitBreakerLike } from './engine-context';

const log = createLogger('engine-server/llm-client');
const _fetch = typeof fetch !== 'undefined' ? fetch : nodeFetch;

// ================================================================
// 熔断器（每 endpoint 独立）
// ================================================================

const ctx = getEngineContext();
const gatewayBreaker = ctx.circuitBreaker.createBreaker('gateway', {
  threshold: 3,
  cooldownMs: 30_000,
  onTrip: (endpoint, failures, lastFailure) => {
    ctx.alerting.notifyCircuitBreakerTrip(endpoint, failures, lastFailure).catch(() => {});
  },
});
const deepseekBreaker = ctx.circuitBreaker.createBreaker('deepseek', {
  threshold: 3,
  cooldownMs: 30_000,
  onTrip: (endpoint, failures, lastFailure) => {
    ctx.alerting.notifyCircuitBreakerTrip(endpoint, failures, lastFailure).catch(() => {});
  },
});

export function getCircuitBreakerStatus(): {
  gateway: ReturnType<CircuitBreakerLike['getStatus']>;
  deepseek: ReturnType<CircuitBreakerLike['getStatus']>;
} {
  return {
    gateway: gatewayBreaker.getStatus(),
    deepseek: deepseekBreaker.getStatus(),
  };
}

// ================================================================
// 类型
// ================================================================

export interface LLMChatParams {
  systemPrompt: string;
  userMessage: string;
  abortSignal?: AbortSignal;
  temperature?: number;
  maxTokens?: number;
  /** 仅 DeepSeek 直连有效。默认不设（text 模式），显式传入才启用 JSON 强制。 */
  responseFormat?: 'json_object' | 'text';
}

export interface LLMChatResult {
  content: string;
  model: string;
  usage?: {
    promptTokens?: number;
    completionTokens?: number;
    totalTokens?: number;
  };
}

// ================================================================
// LLM 调用计数
// ================================================================

let llmCallCount = 0;
const MAX_DAILY_FREE = 500;
const WARNING_THRESHOLD = 100;

function bumpLLMCallCount(): void {
  llmCallCount++;
  if (llmCallCount === WARNING_THRESHOLD) {
    log.info(`⚠️ [engine-server LLM] 调用已达 ${WARNING_THRESHOLD} 次`);
  }
  if (llmCallCount >= MAX_DAILY_FREE) {
    log.info(`🚫 [engine-server LLM] 调用已达 ${MAX_DAILY_FREE} 次上限`);
  }
}

export function getLLMCallStats(): { count: number; maxDaily: number; warningThreshold: number } {
  return { count: llmCallCount, maxDaily: MAX_DAILY_FREE, warningThreshold: WARNING_THRESHOLD };
}

// ================================================================
// 主调用函数
// ================================================================

/**
 * 通过 Gateway 或 fallback DeepSeek 调用 LLM
 *
 * ⚠️ 红线：GATEWAY_HOST 必须指向 ClawOrg 自己的 Gateway（18789），
 *    不能指向 EasyClaw 或其他产品的端口。
 *    如果 GATEWAY_HOST 为空，跳过 Gateway 尝试，直接走 API Key 直连。
 *
 * 熔断：每 endpoint 独立熔断器。Gateway 熔断时自动 fallback 到 DeepSeek。
 * 两者都熔断时抛 CircuitOpenError。
 */
export async function chat(params: LLMChatParams): Promise<LLMChatResult> {
  // 始终合并超时：外部 abortSignal 可能永不被 abort（fire-and-forget 场景），
  // 必须确保每次 LLM 调用都有硬超时兜底，防止 fetch 无限等待导致管线卡死。
  const signal = params.abortSignal
    ? AbortSignal.any([params.abortSignal, AbortSignal.timeout(LLM_TIMEOUT_MS)])
    : AbortSignal.timeout(LLM_TIMEOUT_MS);

  // 如果配置了 ClawOrg 自己的 Gateway，优先走 Gateway（带熔断）
  if (GATEWAY_HOST) {
    try {
      return await gatewayBreaker.call(() => chatViaGateway(params, signal));
    } catch (gatewayErr) {
      if (gatewayErr instanceof CircuitOpenError) {
        log.info('[engine-server LLM] Gateway 已熔断，直接 fallback 到 DeepSeek');
      } else if (llmCallCount <= 3) {
        log.info(`[engine-server LLM] Gateway 不可用，fallback 到直连: ${(gatewayErr as Error).message}`);
      }
    }
  }

  // Fallback: 直连 DeepSeek（带熔断）
  return await deepseekBreaker.call(() => chatViaDeepSeek(params, signal));
}

/**
 * 通过 Gateway 调用 LLM
 */
async function chatViaGateway(params: LLMChatParams, signal: AbortSignal): Promise<LLMChatResult> {
  let res: any; // Response type conflict between node-fetch and undici-types
  try {
    res = await _fetch(`${GATEWAY_HOST}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: LLM_MODEL,
        messages: [
          { role: 'system', content: params.systemPrompt },
          { role: 'user', content: params.userMessage },
        ],
        temperature: params.temperature ?? LLM_TEMPERATURE,
        max_tokens: params.maxTokens ?? LLM_MAX_TOKENS,
        response_format: { type: 'json_object' },
      }),
      signal,
    });
  } catch (fetchErr) {
    log.error(`[engine-server LLM] Gateway fetch 失败: ${(fetchErr as Error).message}`);
    log.error(`[engine-server LLM] cause: ${JSON.stringify((fetchErr as { cause?: unknown }).cause || 'none')}`);
    throw fetchErr;
  }

  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(`Gateway LLM 错误 (${res.status}): ${text.slice(0, 200)}`);
  }

  const data = (await res.json()) as LLMChatCompletionResponse;
  const content = data?.choices?.[0]?.message?.content;

  if (!content) {
    throw new Error('Gateway 返回数据缺少 choices[0].message.content');
  }

  bumpLLMCallCount();

  return {
    content,
    model: data.model || LLM_MODEL,
    usage: data.usage ? {
      promptTokens: data.usage.prompt_tokens,
      completionTokens: data.usage.completion_tokens,
      totalTokens: data.usage.total_tokens,
    } : undefined,
  };
}

/**
 * Fallback: 直连 DeepSeek
 */
async function chatViaDeepSeek(params: LLMChatParams, signal: AbortSignal): Promise<LLMChatResult> {
  if (!DEEPSEEK_API_KEY) {
    throw new Error('LLM API Key 未配置 (DEEPSEEK_API_KEY 或 LLM_API_KEY)');
  }

  let res2: any; // Response type conflict between node-fetch and undici-types
  try {
    const LLM_BASE_URL = process.env.LLM_BASE_URL || 'https://api.deepseek.com';
    res2 = await _fetch(`${LLM_BASE_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${DEEPSEEK_API_KEY}`,
      },
      body: JSON.stringify({
        model: process.env.DEEPSEEK_MODEL || 'deepseek-v4-flash',
        messages: [
          { role: 'system', content: params.systemPrompt },
          { role: 'user', content: params.userMessage },
        ],
        temperature: params.temperature ?? LLM_TEMPERATURE,
        max_tokens: params.maxTokens ?? LLM_MAX_TOKENS,
        ...(params.responseFormat === 'json_object'
          ? { response_format: { type: 'json_object' as const } }
          : {}),
      }),
      signal,
    });
  } catch (fetchErr) {
    log.error(`[engine-server LLM] fetch 失败详情: ${(fetchErr as Error).message}`);
    log.error(`[engine-server LLM] cause: ${JSON.stringify((fetchErr as { cause?: unknown }).cause || 'none')}`);
    throw fetchErr;
  }

  if (!res2.ok) {
    const text = await res2.text().catch(() => '');
    throw new Error(`DeepSeek API 错误 (${res2.status}): ${text.slice(0, 200)}`);
  }

  const data = (await res2.json()) as LLMChatCompletionResponse;
  const content = data?.choices?.[0]?.message?.content;

  if (!content) {
    // 打 full response 的前 500 字符以辅助调试空 content 问题
    log.warn({
      finishReason: data?.choices?.[0]?.finish_reason,
      responsePreview: JSON.stringify(data).slice(0, 500),
    }, '[engine-server LLM] DeepSeek 返回了空 content');
    throw new Error('DeepSeek 返回数据缺少 choices[0].message.content');
  }

  bumpLLMCallCount();

  return {
    content,
    model: 'deepseek-v4-pro',
    usage: data.usage ? {
      promptTokens: data.usage.prompt_tokens,
      completionTokens: data.usage.completion_tokens,
      totalTokens: data.usage.total_tokens,
    } : undefined,
  };
}
